public int NumDecodingsMemo(string s)
{
    int[] memo = new int[s.Length];
    Array.Fill(memo, -1);
    return Decode(0);

    int Decode(int i)
    {
        if (i == s.Length) return 1;
        if (s[i] == '0') return 0;
        if (memo[i] != -1) return memo[i];
        int ways = Decode(i + 1);
        if (i + 1 < s.Length && (s[i] == '1' || (s[i] == '2' && s[i + 1] <= '6')))
            ways += Decode(i + 2);
        memo[i] = ways;
        return ways;
    }
}

public int NumDecodings(string s)
{
    if (string.IsNullOrEmpty(s) || s[0] == '0') return 0;
    int prev = 1, curr = 1;
    for (int i = 1; i < s.Length; i++)
    {
        int temp = 0;
        if (s[i] != '0') temp += curr;
        if (s[i - 1] == '1' || (s[i - 1] == '2' && s[i] <= '6')) temp += prev;
        prev = curr;
        curr = temp;
        if (curr == 0) return 0;
    }
    return curr;
}
